/**
 * MotorsportDB - Client-side search
 *
 * The index generated by bin/build.php is downloaded once (HTTP cached with an
 * ETag) and every keystroke is then resolved in the browser: no request hits
 * the server while typing.
 *
 * Matching is accent/case insensitive, tolerant to small typos, and follows
 * team lineage ("Renault" also finds Alpine, "Toro Rosso" finds Racing Bulls).
 */

const INDEX_URL = '/api/search-index.php';

const FOLD = { 'ø': 'o', 'œ': 'oe', 'æ': 'ae', 'ß': 'ss', 'ł': 'l', 'đ': 'd', 'ð': 'd', 'þ': 'th', 'ı': 'i' };

/** Lowercase, strip accents and punctuation: "Pato_O'Ward" -> "pato o ward". */
export function normalize(text) {
    return String(text ?? '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '')
        .replace(/[øœæßłđðþı]/g, (c) => FOLD[c])
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
}

/** Damerau-Levenshtein distance limited to `max` (returns max + 1 when above). */
function distance(a, b, max) {
    if (Math.abs(a.length - b.length) > max) return max + 1;
    const prev2 = new Array(b.length + 1).fill(0);
    let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
    for (let i = 1; i <= a.length; i++) {
        const cur = [i];
        let rowMin = i;
        for (let j = 1; j <= b.length; j++) {
            const cost = a[i - 1] === b[j - 1] ? 0 : 1;
            let v = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
            if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) {
                v = Math.min(v, prev2[j - 2] + 1);
            }
            cur[j] = v;
            rowMin = Math.min(rowMin, v);
        }
        if (rowMin > max) return max + 1;
        for (let j = 0; j <= b.length; j++) prev2[j] = prev[j];
        prev = cur;
    }
    return prev[b.length];
}

function typoBudget(word) {
    if (word.length >= 8) return 2;
    if (word.length >= 4) return 1;
    return 0;
}

/**
 * Score how well the query words match a list of words (0 = no match).
 * Every query word must match one word (exactly, as a prefix or with a typo).
 */
function matchWords(queryWords, words) {
    let total = 0;
    for (const q of queryWords) {
        let best = 0;
        for (const w of words) {
            if (w === q) { best = 3; break; }
            if (w.startsWith(q)) { best = Math.max(best, 2); continue; }
            const budget = typoBudget(q);
            if (budget && best < 1) {
                // compare with the word, or a prefix of it (the user may still be typing)
                for (let len = q.length - budget; len <= q.length + budget; len++) {
                    if (len > 0 && len <= w.length && distance(q, w.slice(0, len), budget) <= budget) {
                        best = 1;
                        break;
                    }
                }
            }
        }
        if (!best) return 0;
        total += best;
    }
    return total / (3 * queryWords.length);
}

const pictureUrl = (path, fallback) => '/' + (path || fallback);

class SearchIndex {
    constructor() {
        this.entries = null;
        this.loading = null;
    }

    /** Download and prepare the index (only once). */
    load() {
        if (this.entries) return Promise.resolve(this.entries);
        if (!this.loading) {
            this.loading = fetch(INDEX_URL, { headers: { Accept: 'application/json' } })
                .then((r) => {
                    if (!r.ok) throw new Error(`Search index unavailable (HTTP ${r.status})`);
                    return r.json();
                })
                .then((raw) => (this.entries = this.prepare(raw)))
                .catch((err) => {
                    this.loading = null;
                    throw err;
                });
        }
        return this.loading;
    }

    prepare(raw) {
        const entries = [];
        const lineageWords = (raw.l || []).map((names) => names.map((n) => normalize(n).split(' ')));

        const aliasList = (aliases) => (aliases || []).map((name) => ({ name, words: normalize(name).split(' ') }));

        for (const [id, label, country, first, last, picture, nickname, aliases] of raw.d || []) {
            const key = normalize(label);
            entries.push({
                type: 'driver', id, name: label, key,
                words: [...new Set([...key.split(' '), ...normalize(id).split(' '), ...normalize(nickname).split(' ').filter(Boolean)])],
                aliases: aliasList(aliases),
                image: pictureUrl(picture, 'drivers/picture/default.png'),
                url: `/driver?id=${encodeURIComponent(id)}`,
                country, first, last,
            });
        }
        for (const [id, label, country, first, last, picture, group, aliases] of raw.t || []) {
            const key = normalize(label);
            entries.push({
                type: 'team', id, name: label, key,
                words: [...new Set([...key.split(' '), ...normalize(id).split(' ')])],
                aliases: aliasList(aliases),
                lineage: group >= 0 ? { names: raw.l[group], words: lineageWords[group] } : null,
                image: pictureUrl(picture, 'teams/picture/default.png'),
                url: `/team?id=${encodeURIComponent(id)}`,
                country, first, last,
            });
        }
        for (const [id, label, lastYear, picture, firstYear] of raw.c || []) {
            const key = normalize(label);
            const year = lastYear === 0 ? '0000' : String(lastYear);
            entries.push({
                type: 'championship', id, name: label, key,
                words: key.split(' '),
                image: pictureUrl(picture, 'races/picture/default.png'),
                url: `/race?id=${encodeURIComponent(id)}&year=${year}`,
                first: firstYear, last: lastYear,
            });
        }
        return entries;
    }

    /**
     * Search the index.
     * @param {string} query
     * @param {{limit?: number, types?: string[]}} options
     * @returns {Promise<Array>} results sorted by relevance
     */
    async search(query, { limit = 10, types = null } = {}) {
        const entries = await this.load();
        const q = normalize(query);
        if (q.length < 2) return [];
        const qWords = q.split(' ');
        const thisYear = new Date().getFullYear();
        const results = [];

        for (const e of entries) {
            if (types && !types.includes(e.type)) continue;
            let score = 0;
            let via = null;

            if (e.key === q) score = 100;
            else if (e.key.startsWith(q)) score = 85;
            else if (e.key.includes(q)) score = 65;
            else {
                const m = matchWords(qWords, e.words);
                if (m) score = 30 + 40 * m;
            }

            // Other names: "Renault" -> Alpine, "Toro Rosso" -> Racing Bulls…
            for (const alias of score < 100 ? e.aliases || [] : []) {
                if (alias.words.join(' ') === q && score < 92) {
                    score = 92; // exact former name ("Renault" -> Alpine) beats partial matches
                    via = alias.name;
                    continue;
                }
                const m = matchWords(qWords, alias.words);
                if (m && 35 + 35 * m > score) {
                    score = 35 + 35 * m;
                    via = alias.name;
                }
            }

            // Team lineage through previous/next links
            if (score < 60 && e.lineage) {
                e.lineage.words.forEach((words, i) => {
                    const m = matchWords(qWords, words);
                    if (m && 25 + 30 * m > score) {
                        score = 25 + 30 * m;
                        via = e.lineage.names[i];
                    }
                });
            }
            if (!score) continue;

            // Prefer active/recent and long careers on equal relevance.
            if (e.last) score += Math.max(0, 6 - (thisYear - e.last) / 5);
            if (e.first && e.last) score += Math.min(4, (e.last - e.first) / 5);
            if (e.type === 'championship') score += 3;

            results.push({ ...e, score, via: via && normalize(via) !== e.key ? via : null });
        }

        results.sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));
        return results.slice(0, limit).map((r) => ({
            type: r.type,
            id: r.id,
            name: r.name,
            image: r.image,
            url: r.url,
            via: r.via,
            metadata: { country: r.country || null, first: r.first || null, last: r.last || null },
        }));
    }
}

export const searchIndex = new SearchIndex();
export default searchIndex;
